function renderStats(){const n=document.getElementById("stats-grid");n&&"undefined"!=typeof SM_INFO&&(n.innerHTML=SM_INFO.quickStats.map(n=>`\n        <div class="stat-card">\n            <span class="stat-icon">${n.icon}</span>\n            <div class="stat-val">${n.value}</div>\n            <div class="stat-lbl">${n.label}</div>\n        </div>\n    `).join(""))}function renderEcosystem(){if("undefined"==typeof TWIN_LAKE_ECOSYSTEM)return;const n=document.getElementById("eco-overview"),e=document.getElementById("eco-surinsar"),t=document.getElementById("eco-mansar"),i=document.getElementById("eco-hydrology");n&&(n.innerHTML=`<strong>Overview:</strong> ${TWIN_LAKE_ECOSYSTEM.overview}`),e&&(e.innerHTML=`<strong>Surinsar Lake:</strong> ${TWIN_LAKE_ECOSYSTEM.surinsarProfile}`),t&&(t.innerHTML=`<strong>Mansar Lake:</strong> ${TWIN_LAKE_ECOSYSTEM.mansarProfile}`),i&&(i.innerHTML=`<strong>Hydrology & Water Source:</strong> ${TWIN_LAKE_ECOSYSTEM.hydrology}`)}function renderRamsar(){if("undefined"==typeof RAMSAR_DETAILS)return;const n=document.getElementById("ramsar-summary"),e=document.getElementById("ramsar-criteria"),t=document.getElementById("ramsar-threats"),i=document.getElementById("ramsar-conservation");n&&(n.textContent=RAMSAR_DETAILS.summary),e&&(e.innerHTML=RAMSAR_DETAILS.criteria.map(n=>`<li>${n}</li>`).join("")),t&&(t.innerHTML=RAMSAR_DETAILS.threats.map(n=>`<li>${n}</li>`).join("")),i&&(i.innerHTML=`<strong>Conservation & Management:</strong> ${RAMSAR_DETAILS.conservation}`)}function renderReligious(){const n=document.getElementById("religious-grid");n&&"undefined"!=typeof RELIGIOUS_IMPORTANCE&&(n.innerHTML=RELIGIOUS_IMPORTANCE.map(n=>`\n        <div class="sm-card">\n            <span class="sm-card-icon">${n.icon}</span>\n            <h3>${n.title}</h3>\n            <p>${n.description}</p>\n        </div>\n    `).join(""))}function renderWildlife(){const n=document.getElementById("wildlife-grid");n&&"undefined"!=typeof WILDLIFE_SPECIES&&(n.innerHTML=WILDLIFE_SPECIES.map(n=>`\n        <div class="species-card">\n            <div class="species-card-body">\n                <div class="species-header">\n                    <h3>${n.icon} ${n.name}</h3>\n                    <span class="status-badge">${n.status}</span>\n                </div>\n                <p class="scientific-name"><em>${n.scientificName} · ${n.category}</em></p>\n                <p>${n.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderBirds(){const n=document.getElementById("birds-grid");n&&"undefined"!=typeof BIRD_SPECIES&&(n.innerHTML=BIRD_SPECIES.map(n=>`\n        <div class="species-card">\n            <div class="species-card-body">\n                <div class="species-header">\n                    <h3>${n.icon} ${n.name}</h3>\n                    <span class="status-badge">${n.status}</span>\n                </div>\n                <p class="scientific-name"><em>${n.scientificName}</em></p>\n                <p>${n.description}</p>\n                <div class="bird-meta">\n                    <span>🗓️ ${n.season}</span> |\n                    <span>📊 ${n.count}</span>\n                </div>\n            </div>\n        </div>\n    `).join(""))}function renderLegends(){const n=document.getElementById("legends-grid");n&&"undefined"!=typeof LOCAL_LEGENDS&&(n.innerHTML=LOCAL_LEGENDS.map(n=>`\n        <div class="sm-card legend-card">\n            <span class="sm-card-icon">${n.icon}</span>\n            <h3>${n.title}</h3>\n            <p>${n.description}</p>\n        </div>\n    `).join(""))}function renderHotspots(){const n=document.getElementById("hotspots-grid");n&&"undefined"!=typeof MAP_HOTSPOTS&&(n.innerHTML=MAP_HOTSPOTS.map(n=>`\n        <div class="hotspot-card">\n            <h3>📍 ${n.title}</h3>\n            <span class="spot-type">${n.type}</span>\n            <p>${n.description}</p>\n            <small>Coordinates: ${n.lat}° N, ${n.lng}° E</small>\n        </div>\n    `).join(""))}function initMap(){if(!document.getElementById("map-container")||"undefined"==typeof MAP_HOTSPOTS||"undefined"==typeof L)return;const n=L.map("map-container").setView([SM_INFO.coordinates.lat,SM_INFO.coordinates.lng],11);L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",{maxZoom:18,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(n),MAP_HOTSPOTS.forEach(e=>{L.marker([e.lat,e.lng]).addTo(n).bindPopup(`<strong>${e.title}</strong><br/><em>${e.type}</em><br/>${e.description}`)})}function renderGallery(){const n=document.getElementById("gallery-grid");n&&"undefined"!=typeof GALLERY_IMAGES&&(n.innerHTML=GALLERY_IMAGES.map(n=>`\n        <div class="gallery-card">\n            <img src="${n.url}" alt="${n.caption}" loading="lazy" />\n            <p>${n.caption}</p>\n        </div>\n    `).join(""))}function initThemeToggle(){const n=document.getElementById("theme-toggle");n&&n.addEventListener("click",()=>{const e=document.body.classList.toggle("light-theme");localStorage.setItem("theme",e?"light":"dark"),n.textContent=e?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderEcosystem(),renderRamsar(),renderReligious(),renderWildlife(),renderBirds(),renderLegends(),renderHotspots(),initMap(),renderGallery(),initThemeToggle()});